import {giftOpeningSource} from './appearance.js';
import {safeMusicURL,giftContentPages,createExperienceChapters} from './experience.js';
import {createSound} from './audio-studio.js';
import {createPaper} from './paper.js';
export function initReceiving({getData,onReply,onStories}){
 const $=s=>document.querySelector(s),dialog=$('#recipient-dialog'),canvas=$('#gift-canvas'),ctx=canvas.getContext('2d');
 const exampleNotice=document.createElement('p');exampleNotice.className='received-example-notice';exampleNotice.textContent='Exemplo ilustrativo · pessoas e história fictícias. Personalize com suas próprias fotos.';exampleNotice.hidden=true;dialog.prepend(exampleNotice);
 const atlas=new Image();atlas.src='assets/gift-opening-30fps.webp';let ready=atlas.decode();ready.catch(()=>{});let frame=0,raf=0,revealTimer,playing=false,session=0,reader=null,reader3D=null,in3D=false,readerZoom=1;
 const threeMount=document.createElement('div');threeMount.id='reader-three';threeMount.className='reader-three';threeMount.hidden=true;$('#reader-view').append(threeMount);
 const readerStatus=document.createElement('p');readerStatus.className='reader-status';readerStatus.setAttribute('role','status');$('#reader-view').prepend(readerStatus);
 const chapters=document.createElement('div');chapters.className='received-experience';$('#receiving-revealed').append(chapters);let chapterCleanup=()=>{},sound=null,sounding=false,soundPending=false,soundRequest=0;const audioButton=document.createElement('button');audioButton.type='button';audioButton.className='button outline receive-audio';audioButton.textContent='Ouvir o áudio';chapters.before(audioButton);function renderAudio(){audioButton.textContent=soundPending?'Cancelar carregamento':sounding?'Pausar áudio':receivedData?.experience?.audioKind==='music'?'Ouvir a música':'Ouvir o áudio';audioButton.setAttribute('aria-busy',String(soundPending));audioButton.setAttribute('aria-pressed',String(sounding));}
 audioButton.addEventListener('click',async()=>{if(sounding||soundPending){soundRequest++;sound?.pause();soundPending=false;sounding=false;renderAudio();return;}if(!receivedData)return;const ownSession=session,request=++soundRequest;if(!sound){const player=createSound(receivedData.experience,receivedData.audioUrl,{onEnded:()=>{if(sound!==player)return;soundRequest++;soundPending=false;sounding=false;renderAudio();}});sound=player;}const player=sound,current=()=>session===ownSession&&sound===player&&request===soundRequest;soundPending=true;renderAudio();try{const playing=await player.play();if(!current())return;soundPending=false;sounding=playing;renderAudio();if(!playing)audioButton.textContent='Áudio indisponível';}catch{if(!current())return;soundPending=false;sounding=false;renderAudio();audioButton.textContent='Áudio indisponível';}});
 let ready3D=null,contentOpen=false,receivedData=null,pageIndex=0,chosenPhoto=null,pageBusy=false;
 const musicLink=document.createElement('a');musicLink.className='button outline receive-music-link';musicLink.textContent='Ouvir a música escolhida ↗';musicLink.target='_blank';musicLink.rel='noopener noreferrer';musicLink.hidden=true;audioButton.after(musicLink);
 function readerData(at=pageIndex,useSelection=true){const data=receivedData??getData();const page=data.format==='livro'?giftContentPages(data)[at]:null;return {...data,...(page?{pageTitle:page.title,message:page.message,photo:page.photo}:{}),...(useSelection&&chosenPhoto?{photo:chosenPhoto}:{})};}
 const pageNav=document.createElement('nav');pageNav.className='reader-page-nav';pageNav.setAttribute('aria-label','Páginas do presente');pageNav.innerHTML='<button class="reader-previous" type="button">← Anterior</button><span class="reader-page-count" aria-live="polite"></span><button class="reader-next" type="button">Próxima →</button>';$('#reader-view').append(pageNav);
 function pageControls(){const data=receivedData??getData(),count=giftContentPages(data).length;pageNav.hidden=data.format!=='livro'||count<2;pageNav.querySelector('.reader-previous').disabled=pageBusy||pageIndex===0;pageNav.querySelector('.reader-next').disabled=pageBusy||pageIndex>=count-1;pageNav.querySelector('.reader-page-count').textContent='Página '+(pageIndex+1)+' de '+count;$('#reader-view').dataset.page=String(pageIndex);}
 async function turnPage(delta){if(pageBusy)return;const count=giftContentPages(receivedData??getData()).length,next=Math.max(0,Math.min(count-1,pageIndex+delta));if(next===pageIndex)return;const ownSession=session;pageBusy=true;pageControls();try{if(reader3D){const ok=await reader3D.turn(readerData(next,false),delta);if(ok===false||ownSession!==session)return;}if(ownSession!==session)return;pageIndex=next;chosenPhoto=null;contentOpen=true;fill();reader3D?.open(true);reader?.set(readerData());reader?.open(true);$('#receive-book').firstChild.textContent='Ver capa ';$('#receive-book').setAttribute('aria-expanded','true');}finally{if(ownSession===session){pageBusy=false;pageControls();}}}
 pageNav.querySelector('.reader-previous').addEventListener('click',()=>turnPage(-1));pageNav.querySelector('.reader-next').addEventListener('click',()=>turnPage(1));
 
 $('#receiving-revealed').insertBefore($('#reader-view'),document.querySelector('.received-memory'));
 $('#receiving-revealed').insertBefore(document.querySelector('.received-actions'),$('#reader-view'));
 const details=document.createElement('details');details.className='read-message-details';const summary=document.createElement('summary');summary.textContent='Ler a mensagem em texto';details.append(summary);document.querySelector('.received-memory').before(details);details.append(document.querySelector('.received-memory'),$('#larger-text'));details.open=true;
 const photoNav=document.createElement('div');photoNav.className='received-photo-choices';photoNav.setAttribute('role','group');photoNav.setAttribute('aria-label','Fotos deste mimo');details.insertBefore(photoNav,$('#larger-text'));
 function photoChoices(){const data=receivedData??getData();photoNav.replaceChildren();photoNav.hidden=data.format!=='stories'||!data.photos?.length;if(photoNav.hidden)return;data.photos.forEach((photo,i)=>{const button=document.createElement('button');button.type='button';button.setAttribute('aria-label','Ver foto '+(i+1));const img=document.createElement('img');img.src=photo.src;img.alt='';button.append(img);button.dataset.photoSrc=photo.src;button.setAttribute('aria-pressed',String(photo.src===readerData().photo));button.addEventListener('click',()=>{chosenPhoto=photo.src;fill();reader3D?.set(readerData());reader?.set(readerData());});photoNav.append(button);});}
 
 const rsvp=document.createElement('form');rsvp.className='rsvp-preview';rsvp.hidden=true;rsvp.innerHTML='<p class="rsvp-local-label">Teste de confirmação · apenas neste aparelho</p><h3>Você vem celebrar?</h3><label for="rsvp-name">Seu nome no convite</label><input id="rsvp-name" maxlength="80" required placeholder="Seu nome ou o da família"><div class="rsvp-options" role="group" aria-label="Sua resposta"><button type="button" data-answer="accepted" aria-pressed="true">Vou participar</button><button type="button" data-answer="declined" aria-pressed="false">Não poderei ir</button></div><label for="rsvp-count">Quantas pessoas ao todo?</label><select id="rsvp-count"></select><button type="submit" class="button primary">Confirmar nesta prévia</button><p class="rsvp-result" role="status"></p>';details.after(rsvp);
 const rsvpButton=document.createElement('button');rsvpButton.type='button';rsvpButton.className='button outline recipient-rsvp';rsvpButton.textContent='Confirmar presença';document.querySelector('.received-actions').append(rsvpButton);rsvpButton.addEventListener('click',()=>{rsvp.scrollIntoView({behavior:'instant',block:'start'});rsvp.querySelector('#rsvp-name').focus({preventScroll:true});});let replyStatus='accepted';
 function setAnswer(status){replyStatus=status;rsvp.querySelectorAll('[data-answer]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.answer===status)));rsvp.querySelector('#rsvp-count').disabled=status==='declined';}
 rsvp.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>setAnswer(button.dataset.answer)));
 function prepareRSVP(){const data=readerData(),guest=data.guestPreview;rsvp.hidden=data.format!=='convite';rsvpButton.hidden=rsvp.hidden;const name=rsvp.querySelector('#rsvp-name');name.value=guest?.name??'';name.readOnly=!!guest;const select=rsvp.querySelector('#rsvp-count');select.replaceChildren();for(let count=1;count<=(guest?.allowedCount??1);count++)select.add(new Option(String(count),String(count)));select.value=String(guest?.attendingCount||1);setAnswer(guest?.status==='declined'?'declined':'accepted');rsvp.querySelector('.rsvp-result').textContent='Esta é uma prévia. Nenhuma resposta será enviada a outra pessoa.';}
 rsvp.addEventListener('submit',event=>{event.preventDefault();const data=readerData(),count=replyStatus==='declined'?0:Number(rsvp.querySelector('#rsvp-count').value),guest=data.guestPreview;const saved=guest&&onReply?.({id:guest.id,status:replyStatus,count});if(guest)receivedData.guestPreview={...guest,status:replyStatus,attendingCount:count};rsvp.querySelector('.rsvp-result').textContent=saved?'Resposta guardada nesta prévia, neste aparelho. Você pode mudar as escolhas e confirmar novamente.':'Você concluiu o teste de confirmação. Nenhuma resposta foi enviada.';});
 async function prepareReader(){
  const ownSession=session;$('#reader-view').hidden=false;readerStatus.textContent='Seu mimo está ganhando forma…';threeMount.hidden=false;$('#reader-paper').hidden=true;
  try{
   if(!reader3D){if(!ready3D)ready3D=import('./book.js').then(({createBook})=>createBook(threeMount,readerData())).then(value=>{reader3D=value;return value;}).finally(()=>{ready3D=null;});await ready3D;}
   if(ownSession!==session||!dialog.open)return;
   in3D=true;metrics.renderer='three';reader3D.set(readerData());reader3D.open(contentOpen);reader3D.motion(getData().motionPaused);reader3D.zoom(readerZoom);readerStatus.textContent='Seu mimo se abre aqui. Use os botões para ampliar.';
  }catch{
   if(ownSession!==session||!dialog.open)return;in3D=false;metrics.renderer='2d-fallback';threeMount.hidden=true;$('#reader-paper').hidden=false;
   if(!reader)reader=createPaper($('#reader-paper'),readerData());else reader.set(readerData());reader.open(contentOpen);reader.zoom(readerZoom);readerStatus.textContent='Seu mimo está disponível em leitura simples neste aparelho.';
  }
 }
 const metrics={targetFps:30,totalFrames:90,renderedFrames:0,frameIndices:[],elapsedMs:0,state:'closed'};
 const draw=n=>{frame=n;const x=n%10,y=Math.floor(n/10);ctx.clearRect(0,0,600,600);ctx.drawImage(atlas,x*320,y*320,320,320,0,0,600,600);canvas.dataset.frame=String(n);};
 const skin=(el,data)=>{el.className='sprite '+data.theme.sheet+' row'+data.theme.row+' '+(el.id==='delivery-capi'?'delivery-capi':'received-capi');el.style.setProperty('--frame-x',(data.theme.col||0)*100/3+'%');};
 function fill(){const data=readerData();pageControls();photoNav.querySelectorAll('button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.photoSrc===data.photo)));$('#receiving-eyebrow').textContent=data.format==='convite'?(data.guestPreview?'Para '+data.guestPreview.name+'.':'Um convite para celebrar.'):(data.recipient?'Para '+data.recipient+'.':'Alguém lembrou de você.');$('#received-message').textContent=data.message||'Que bom ter você na minha história.';$('#revealed-title').textContent=data.format==='convite'?(data.recipient?data.recipient+' convidam você.':'Você faz parte deste dia.'):(data.recipient?'Um mimo para '+data.recipient+'.':'Feito para você.');skin($('#delivery-capi'),data);skin($('#received-capi'),data);const photo=$('#received-photo');photo.hidden=!data.photo;if(data.photo)photo.src=data.photo;else photo.removeAttribute('src');$('#received-capi').hidden=!!data.photo;const date=data.eventDate?new Date(data.eventDate+'T12:00:00').toLocaleDateString('pt-BR'):'';$('#received-event').hidden=data.format!=='convite';$('#received-event').textContent=[date,data.eventPlace].filter(Boolean).join(' · ');$('#receive-book').firstChild.textContent=data.format==='livro'?'Abrir meu livro ':data.format==='convite'?'Abrir meu convite ':'Abrir meu cartão ';$('#receive-book').setAttribute('aria-expanded','false');}
 function reset(){soundRequest++;sound?.stop();sound=null;sounding=false;soundPending=false;renderAudio();pageBusy=false;const opening=giftOpeningSource(receivedData||getData());if(!atlas.src.endsWith('/'+opening)){atlas.src=opening;ready=atlas.decode();ready.catch(()=>{});}pageIndex=0;chosenPhoto=null;photoChoices();prepareRSVP();session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);playing=false;in3D=false;readerZoom=1;threeMount.hidden=true;$('#reader-paper').hidden=false;contentOpen=false;metrics.renderer='loading';metrics.state='sealed';$('#receiving-sealed').hidden=false;$('#receiving-revealed').hidden=true;$('#reader-view').hidden=true;$('#unwrap-gift').disabled=true;$('#unwrap-gift').textContent='Preparando seu mimo…';$('#receiving-hint').textContent='A surpresa é sua. Abra no seu tempo.';canvas.setAttribute('aria-label','Presente fechado com um laço vermelho');ready.then(()=>{draw(0);$('#unwrap-gift').disabled=false;$('#unwrap-gift').textContent='Abrir meu presente';}).catch(()=>{$('#unwrap-gift').disabled=false;$('#unwrap-gift').textContent='Abrir a mensagem';});fill();}
 function reveal(){metrics.state='revealed';contentOpen=true;$('#receive-book').firstChild.textContent='Ver capa ';$('#receive-book').setAttribute('aria-expanded','true');prepareReader();$('#receiving-sealed').hidden=true;$('#receiving-revealed').hidden=false;dialog.scrollTop=0;$('#receive-book').focus({preventScroll:true});}
 function play(){if(playing)return;playing=true;const ownSession=session;$('#unwrap-gift').disabled=true;$('#unwrap-gift').textContent='Um carinho se abrindo…';$('#receiving-hint').textContent='Preparado com você em cada detalhe.';metrics.frameIndices=[];metrics.renderedFrames=0;metrics.state='playing';
  if(getData().motionPaused||!atlas.complete||!atlas.naturalWidth){if(atlas.naturalWidth)draw(89);reveal();return;}
  let start;const tick=t=>{if(ownSession!==session)return;if(start===undefined)start=t;const index=Math.min(89,Math.floor((t-start)*30/1000));if(index!==frame||metrics.renderedFrames===0){draw(index);metrics.frameIndices.push(index);metrics.renderedFrames++;}metrics.elapsedMs=t-start;if(index<89){raf=requestAnimationFrame(tick);}else{canvas.setAttribute('aria-label','Presente aberto; uma carta com coração saiu da caixa');revealTimer=setTimeout(reveal,500);}};raf=requestAnimationFrame(tick);
 }
 const show=(options={})=>{const source=options.data||getData();exampleNotice.hidden=!source.isExample;if(source.format==='stories'&&onStories){onStories(source);return;}receivedData={...source,...(options.guestPreview?{guestPreview:{...options.guestPreview}}:{})};chapterCleanup();chapterCleanup=createExperienceChapters(chapters,receivedData);soundRequest++;sound?.stop();sound=null;sounding=false;soundPending=false;renderAudio();const musicUrl=safeMusicURL(receivedData.experience?.musicUrl);musicLink.hidden=receivedData.experience?.sound!=='link'||!musicUrl;if(musicUrl)musicLink.href=musicUrl;audioButton.textContent=receivedData.experience?.audioKind==='music'?'Ouvir a música':'Ouvir o áudio';audioButton.hidden=!receivedData.experience||!['file','musicbox'].includes(receivedData.experience.sound)||receivedData.experience.sound==='file'&&!receivedData.audioUrl;reset();dialog.showModal();document.body.style.overflow='hidden';};
 $('#recipient-preview').addEventListener('click',()=>show());
 $('#unwrap-gift').addEventListener('click',play);$('#replay-gift').addEventListener('click',reset);
 const unlock=()=>{if(metrics.state==='closed')return;chapterCleanup();soundRequest++;sound?.stop();sound=null;sounding=false;soundPending=false;renderAudio();session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);document.body.style.overflow='';metrics.state='closed';};
 $('#recipient-close').addEventListener('click',()=>{dialog.close();unlock();});dialog.addEventListener('close',()=>{if(!dialog.open)unlock();});
 $('#receive-book').addEventListener('click',()=>{contentOpen=!contentOpen;reader3D?.open(contentOpen);reader?.open(contentOpen);$('#receive-book').setAttribute('aria-expanded',String(contentOpen));$('#receive-book').firstChild.textContent=contentOpen?'Ver capa ':readerData().format==='livro'?'Abrir meu livro ':readerData().format==='convite'?'Abrir meu convite ':'Abrir meu cartão ';$('#reader-view').scrollIntoView({behavior:getData().motionPaused?'instant':'smooth',block:'nearest'});});
 const zoomReader=value=>{readerZoom=Math.max(1,Math.min(2.2,value));reader?.zoom(readerZoom);reader3D?.zoom(readerZoom);$('#reader-view').dataset.zoom=String(readerZoom);};
 $('#reader-plus').addEventListener('click',()=>zoomReader(readerZoom+.2));$('#reader-minus').addEventListener('click',()=>zoomReader(readerZoom-.2));$('#reader-fit').addEventListener('click',()=>{reader3D?.resetView();zoomReader(1);});
 $('#skip-opening').addEventListener('click',()=>{session++;cancelAnimationFrame(raf);clearTimeout(revealTimer);reveal();});
 $('#larger-text').addEventListener('click',()=>{const large=dialog.classList.toggle('large-reading');$('#larger-text').setAttribute('aria-pressed',String(large));$('#larger-text').textContent=large?'Voltar ao tamanho normal':'Aumentar texto';});
 metrics.readerSnapshot=()=>reader3D?.snapshot();
 window.__giftAnimation=metrics;
 return {show,snapshot:()=>reader3D?.snapshot()};
}
